<script setup>
import { onMounted,ref } from "vue";
import { NButton,NEmpty,NModal,NInput,NTag,useDialog,useMessage } from "naive-ui";
import PageShell from "../components/PageShell.vue";import Panel from "../components/Panel.vue";
import { pluginsApi } from "../api.js";import { can } from "../access.js";
const items=ref([]),loading=ref(false),error=ref(""),open=ref(false),manifest=ref(""),busy=ref(false);const dialog=useDialog(),message=useMessage();
async function load(){loading.value=true;error.value="";try{items.value=await pluginsApi.list();}catch(e){error.value=e.message;}finally{loading.value=false;}}
async function install(){busy.value=true;try{let input;try{input=JSON.parse(manifest.value);}catch{throw Error("清单不是合法的 JSON，请检查格式");}await pluginsApi.import(input);open.value=false;manifest.value="";await load();message.success("插件已导入");}catch(e){message.error(e.message);}finally{busy.value=false;}}
async function toggle(item){busy.value=true;try{await pluginsApi.patch(item.id,!item.enabled);await load();}catch(e){message.error(e.message);}finally{busy.value=false;}}
function remove(item){dialog.warning({title:"卸载插件",content:`卸载「${item.name}」将移除其技能与 MCP 服务，确定继续？`,positiveText:"卸载",negativeText:"取消",onPositiveClick:async()=>{try{await pluginsApi.remove(item.id);await load();}catch(e){message.error(e.message);return false;}}});}onMounted(load);
</script>
<template><PageShell title="插件" subtitle="通过清单安装可复用技能和外部工具服务" :loading="loading" :error="error"><template #actions><n-button v-if="can('workflow.write')" type="primary" @click="open=true">导入插件</n-button></template><Panel title="已安装插件"><n-empty v-if="!items.length" description="还没有安装插件" class="empty-state"/><article v-for="item in items" :key="item.id" class="plugin-row"><div><h3>{{item.name}} <n-tag size="small">{{item.version}}</n-tag></h3><p class="hint">{{item.description||'暂无说明'}}</p><p class="secondary">{{item.skills?.length??0}} 个技能 · {{item.tools?.length??0}} 个工具</p></div><div v-if="can('workflow.write')" class="action-row"><n-tag :type="item.enabled?'success':'default'">{{item.enabled?'已启用':'已停用'}}</n-tag><n-button :loading="busy" @click="toggle(item)">{{item.enabled?'停用':'启用'}}</n-button><n-button quaternary type="error" @click="remove(item)">卸载</n-button></div></article></Panel><n-modal v-model:show="open" preset="card" title="导入插件清单" style="width:640px"><p class="hint">粘贴 biz-agent.plugin.v1 JSON 清单。清单不执行脚本，凭证在对应服务中单独配置。</p><n-input v-model:value="manifest" type="textarea" :autosize="{minRows:10,maxRows:20}" placeholder="粘贴插件 JSON 清单"/><template #footer><div class="action-row"><n-button @click="open=false">取消</n-button><n-button type="primary" :loading="busy" @click="install">导入</n-button></div></template></n-modal></PageShell></template><style scoped>.plugin-row{padding:18px 0;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap}.plugin-row h3{margin:0;font-size:16px}</style>
